import java.io.OutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.io.PrintStream;
import java.util.Arrays;
import java.util.InputMismatchException;
import java.io.IOException;
import java.util.Comparator;
import java.io.InputStream;

/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 *
 * @author dsh_bc
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskB solver = new TaskB();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskB {
        public void solve(int testNumber, InputReader scanner, PrintWriter out) {
            int n = scanner.nextInt();
            int k = scanner.nextInt();
            int[] oddEven = new int[n];
            int[] arr = new int[n];
            for (int i = 0; i < n; i++) {
                arr[i] = scanner.nextInt();
                if (i == 0) {
                    if (arr[i] % 2 == 0) {
                        oddEven[i] = 1;
                    } else oddEven[i] = -1;
                    continue;
                }
                if (arr[i] % 2 == 0) {
                    oddEven[i] = oddEven[i - 1] + 1;
                } else oddEven[i] = oddEven[i - 1] - 1;
            }
            node[] diffArr = new node[n - 1];
            for (int i = 0; i < n - 1; i++) {
                diffArr[i] = new node();
                diffArr[i].diff = Math.abs(arr[i + 1] - arr[i]);
                diffArr[i].indx = i;
                //System.out.println(diffArr[i].diff+" "+diffArr[i].indx);
            }
            int ans = 0;
            Arrays.sort(diffArr, new node());
            for (int i = 0; i < n - 1; i++) {
                if (k >= diffArr[i].diff && oddEven[diffArr[i].indx] == 0) {
                    if (k - diffArr[i].diff >= 0) {
                        ans++;
                        k = k - diffArr[i].diff;
                    }

                }
            }
            System.out.println(ans);
        }

    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private InputReader.SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public boolean isSpaceChar(int c) {
            if (filter != null) {
                return filter.isSpaceChar(c);
            }
            return isWhitespace(c);
        }

        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int ch);

        }

    }

    static class node implements Comparator<node> {
        int diff;
        int indx;


        public int compare(node o1, node o2) {
            if (o1.diff - o2.diff != 0)
                return o1.diff - o2.diff;
            else return o1.indx - o2.indx;
        }

    }
}


